<template><main class="auth-page"><section class="auth-shell"><p class="auth-kicker">Email choices</p><h1>{{loading?'Updating your preference...':success?'You are unsubscribed':'Unable to unsubscribe'}}</h1><p class="auth-message" :class="{error:!loading&&!success}">{{message}}</p><div v-if="!loading" class="auth-links"><NuxtLink :to="`/email/preferences?token=${encodeURIComponent(token)}`">Review all email preferences</NuxtLink><NuxtLink to="/">Return home</NuxtLink></div></section></main></template>
<script setup lang="ts">useNoIndex();const route=useRoute();const token=typeof route.query.token==='string'?route.query.token:'';const key=typeof route.query.category==='string'?route.query.category:'MARKETING';const loading=ref(true);const success=ref(false);const message=ref('Please wait.');const auth=useMemberAuth();onMounted(async()=>{if(!token){loading.value=false;message.value='The unsubscribe link is incomplete.';return}try{await auth.unsubscribe(token,key);success.value=true;message.value='You will no longer receive emails in this category. Essential transactional messages remain enabled.'}catch(e){message.value=e instanceof Error?e.message:'This unsubscribe link is invalid or expired.'}finally{loading.value=false}});</script>
